// One entry point for both triggers, so the scheduled digest and the on-demand one can
// never drift apart.
//
// The Schedule Trigger emits a timestamp; the Execute Workflow Trigger emits whatever the
// caller passed, which for a manual request is { user }. Presence of `user` is what
// distinguishes them.
const inp = $input.first().json || {};
const manual = Boolean(inp.user);

// Manila-local "today". The trigger fires at 09:00 Manila, but Date is UTC-based, so the
// offset has to be applied before reading the calendar date.
const nowManila = new Date(Date.now() + 8 * 3600 * 1000);
const Y = nowManila.getUTCFullYear();
const M = nowManila.getUTCMonth();
const D = nowManila.getUTCDate();

// The last weekday of the month. Cron cannot express this — there is no such expression —
// so the trigger fires every day from the 25th and this gates it. Walking back from the
// last calendar day handles months that end on a weekend: if the 31st is a Sunday, the
// digest goes out on Friday the 29th.
function lastWeekdayOfMonth(year, monthIndex) {
  const d = new Date(Date.UTC(year, monthIndex + 1, 0));   // day 0 of next month = last day
  while (d.getUTCDay() === 0 || d.getUTCDay() === 6) d.setUTCDate(d.getUTCDate() - 1);
  return d.getUTCDate();
}

// A manual request always runs. A scheduled one runs only on the day itself — returning
// no items stops the branch, so the other six firings do nothing.
if (!manual && D !== lastWeekdayOfMonth(Y, M)) return [];

// Handoff §7: the monthly digest goes to regie and tara. §14.11 asked for a preview to
// tara first; enabled for both on 2026-08-31 after reviewing the rendered output.
//
// Recipients receive it automatically — Posty opens the DM itself, so nobody needs to have
// interacted with it first. Anyone can also request one at any time by DMing "digest",
// which routes here through the Execute Workflow trigger.
const SCHEDULED_RECIPIENTS = [
  'U025597KZ',   // regie
  'U026N6E1R',   // tara
];

return [{ json: {
  mode: manual ? 'manual' : 'scheduled',
  recipients: manual ? [inp.user] : SCHEDULED_RECIPIENTS,
  // Manila-local date. The digest is "as of" the day it runs, in the studio's own timezone.
  as_of: new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10),
} }];

