const POST_ENGINEERS = {
  'U025597KZ':   'regie',
  'U029T6N7U':   'philip',
  'U026N6E1R':   'tara',
  'U04DLRCAA':   'glenn',
  'U6UAKUP08':   'whannie',
  'U026LMLM4':   'rico',
  'U026N9FV9':   'vener',
  'U026N7KR7':   'topet',
  'U026MTBLM':   'richard',
  'U026R9SUQ':   'eddie boy',
  'U08V83R45QV': 'elijah',
  'U08V3CKDGJF': 'howard',
};

function engineerName(user) {
  const u = String(user || '').trim();
  return POST_ENGINEERS[u] || 'unassigned';
}

// Posty — Workflow 3's digest builder.
//
// Handoff §7 Workflow 3. Reads the index only; makes zero Slack history calls. Pure, so
// ./scripts/test-nodes can run it offline against real numbers.
//
// Used by BOTH the monthly scheduled run and the on-demand request, so the two can never
// disagree about what "open" means.



const MAX_BLOCK = 3500;   // Slack caps a text block at 5,000 chars; leave headroom (§7)

function escapeForSlack(t) {
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function ageDays(postedDate, asOf) {
  const a = Date.parse(String(postedDate) + 'T00:00:00Z');
  const b = Date.parse(String(asOf) + 'T00:00:00Z');
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  return Math.round((b - a) / 86400000);
}

// "1 Sep 2026" — the format §7's example uses.
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function humanDate(iso) {
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return String(iso);
  return String(Number(m[3])) + ' ' + MONTHS[Number(m[2]) - 1] + ' ' + m[1];
}

// One line per project: the original post text, then its age. §7's example format is the
// source text itself — nearly every post already opens with its QU number, so prefixing
// one produces "QU-13639 / QU-13639 / Saatchi...". Where a post does NOT lead with a code
// (a pro bono job, or "ay sori po eto pala QU-13864 / ..."), the text still carries
// whatever identification exists, which is the most honest thing to print.
// Widest line that fits without horizontal scrolling in a Slack code block on a laptop.
// Longer titles are truncated: the QU number leads every line so it is never the part
// that gets cut, and the full text is always in the Sheet and in the original post.
const LINE_WIDTH = 80;

// Lines inside a code block are NOT escaped.
//
// Slack renders code-block content literally, so an escaped "&amp;" would display as the
// five characters &amp; rather than an ampersand. A bare & is safe either way — it is not
// an entity, so it survives both literal rendering and entity decoding. Escaping is for
// text Slack will interpret; this text it will not.
function codeLine(row, age) {
  const text = String(row.source_text || '').replace(/\s*\n\s*/g, ' ').trim();
  const room = LINE_WIDTH - 7;
  const body = text.length > room ? text.slice(0, room - 1) + '…' : text;
  return String(age).padStart(4) + 'd  ' + body;
}

function releasedLine(row) {
  const text = String(row.source_text || '').replace(/\s*\n\s*/g, ' ').trim();
  return text.length > LINE_WIDTH ? text.slice(0, LINE_WIDTH - 1) + '…' : text;
}

// Split a section into as many messages as it needs. §7: if a bucket overflows, split
// rather than dropping rows — a digest that silently truncates is worse than two messages,
// because the rows it drops are the ones nobody is looking at.
// Split a section into as many messages as it needs. §7: if a bucket overflows, split
// rather than dropping rows — a digest that silently truncates is worse than two messages,
// because the rows it drops are the ones nobody is looking at.
//
// Code fences must never straddle a split, or one message ends with an unclosed ``` and
// the next starts with a stray one. When a split lands inside a fence, close it before the
// break and reopen it after.
function chunk(header, lines) {
  if (!lines.length) return [];
  const out = [];
  let buf = header;
  let inFence = false;
  for (const l of lines) {
    if (buf.length + l.length + 1 > MAX_BLOCK) {
      out.push(inFence ? buf + '\n```' : buf);
      buf = header + ' (cont.)' + (inFence ? '\n```' : '');
    }
    buf += '\n' + l;
    if (l === '```') inFence = !inFence;
  }
  out.push(inFence ? buf + '\n```' : buf);
  return out;
}

// Group a bucket by the engineer who announced each project.
//
// Engineers are ordered by their OLDEST project, not by count — a person with two 500-day
// jobs needs chasing before someone with eight at 50 days. Within each engineer, oldest
// first, same as everywhere else.
//
// A single-engineer bucket gets no headings: when someone requests their own digest, or
// only one person has anything overdue, the names are noise.
function groupByEngineer(entries, nameOf) {
  const groups = new Map();
  for (const e of entries) {
    const who = nameOf(e.row.posted_by);
    if (!groups.has(who)) groups.set(who, []);
    groups.get(who).push(e);
  }
  const ordered = [...groups.entries()]
    .map(([who, list]) => ({ who, list, oldest: Math.max(...list.map((x) => x.age)) }))
    .sort((a, b) => b.oldest - a.oldest);
  return ordered;
}

// One bucket, grouped by engineer unless there is only one of them.
//
// Projects sit in a monospace block so the ages form a scannable column and the long
// slash-separated titles stop wrapping into each other. The engineer heading stays OUTSIDE
// the block — Slack ignores *bold* inside code fences.
