  const over120 = open.filter((o) => o.age >= 120);
  const band90 = open.filter((o) => o.age >= 90 && o.age < 120);
  const band60 = open.filter((o) => o.age >= 60 && o.age < 90);
  const band30 = open.filter((o) => o.age >= 30 && o.age < 60);
  const fresh = open.filter((o) => o.age < 30);

  const messages = [];
  const title = mode === 'manual'
    ? 'Posty — open projects as of ' + humanDate(asOf) + '  (requested)'
    : 'Posty — open projects as of ' + humanDate(asOf);

  let head = title;
  if (!over120.length && !band90.length && !band60.length && !band30.length) {
    head += '\n\nNothing over 30 days. ' + fresh.length + ' project' +
            (fresh.length === 1 ? '' : 's') + ' open and under 30 days.';
    messages.push(head);
  } else {
    messages.push(head);
    // Empty bands are skipped rather than printed as "(0)". With three of them, a run of
    // zero-count headers is noise that pushes the real work further down the DM.
    const bands = [['🔴 120+ days', over120], ['🟠 90–119 days', band90],
                   ['🟡 60–89 days', band60], ['🟢 30–59 days', band30]];
    for (const [label, bucket] of bands) {
      if (bucket.length) {
        messages.push(...chunk(label + ' (' + bucket.length + ')', renderBucket(bucket, nameOf)));
      }
    }
  }

  // Released this month — flat chronological log, matched on release_date's YYYY-MM.
  const month = String(asOf || '').slice(0, 7);
  const releasedThisMonth = rows.filter((r) =>
    String(r.status || '').trim() === 'RELEASED' &&
    String(r.release_date || '').startsWith(month));
  releasedThisMonth.sort((a, b) =>
    String(a.release_date).localeCompare(String(b.release_date)));
  if (releasedThisMonth.length) {
    const monthLabel = humanDate(month + '-01').replace(/^\d+ /, '');
    messages.push(...chunk('✅ Released in ' + monthLabel + ' (' + releasedThisMonth.length + ')',
      releasedThisMonth.map((r, i) => (i + 1) + '. ' + releasedLine(r))));
  }

  // §7 step 5. These carry no QU at all — not even a synthetic one — so no automation can
  // resolve them. Listed so they are visible, not so they can be actioned.
  //
  // The index deliberately keeps every unmatched message (§9 note 5 calls that acceptable
  // noise), which means UNTRACKED also collects plain channel chatter — "salamuch",
  // "Corgrats Eli!", a bare @mention. Those are noise in the index and merely untidy; in a
  // digest sent to two people they make the whole thing look unreliable.
  //
  // Every real project post in this channel uses " / " between fields. Requiring a slash
  // separates "QU-______ / SPOTIFY / Lea Lardizabal / H&M" — a real job awaiting a code —
  // from "this is DENTSU pala". The filter is presentation only: nothing is dropped from
  // the index, and the omitted count is printed so the filter can never hide a surprise.
  const realUntracked = untracked.filter((r) => String(r.source_text || '').includes('/'));
  const noise = untracked.length - realUntracked.length;

  if (realUntracked.length) {
    let header = 'Not tracked (' + realUntracked.length + ') — no QU code, needs manual check';
    if (noise) header += '\n(' + noise + ' non-project message' + (noise === 1 ? '' : 's') + ' omitted)';
    messages.push(...chunk(header,
      realUntracked.map((r) => escapeForSlack(r.source_text || '').replace(/\s*\n\s*/g, ' ').trim())));
  }

  // Row-count warning. The index grows ~500 released rows a year and full-sheet reads
  // slow past a few thousand. Warn well ahead — in the monthly digest Tara already reads —
  // so old released rows can be archived before it hurts. Tara, 2026-09-08.
  const SIZE_WARN = 4000;
  if (rows.length >= SIZE_WARN) {
    messages.push('🗄️ Heads up: the index is at ' + rows.length + ' rows. Past ~5,000, old '
      + 'released rows should be archived to keep Posty fast — worth planning, not urgent.');
  }

  return {
    messages,
    summary: {
      rows_total: rows.length,
      over120: over120.length,
      band90: band90.length,
      band60: band60.length,
      band30: band30.length,
      under30: fresh.length,
      untracked: realUntracked.length,
      untracked_noise: noise,
      total_open: open.length,
      released_this_month: releasedThisMonth.length,
    },
  };
}

