// because the rows it drops are the ones nobody is looking at.
// Split a section into as many messages as it needs. §7: if a bucket overflows, split
// rather than dropping rows — a digest that silently truncates is worse than two messages,
// because the rows it drops are the ones nobody is looking at.
//
// Code fences must never straddle a split, or one message ends with an unclosed ``` and
// the next starts with a stray one. When a split lands inside a fence, close it before the
// break and reopen it after.
function chunk(header, lines) {
  if (!lines.length) return [];
  const out = [];
  let buf = header;
  let inFence = false;
  for (const l of lines) {
    if (buf.length + l.length + 1 > MAX_BLOCK) {
      out.push(inFence ? buf + '\n```' : buf);
      buf = header + ' (cont.)' + (inFence ? '\n```' : '');
    }
    buf += '\n' + l;
    if (l === '```') inFence = !inFence;
  }
  out.push(inFence ? buf + '\n```' : buf);
  return out;
}

// Group a bucket by the engineer who announced each project.
//
// Engineers are ordered by their OLDEST project, not by count — a person with two 500-day
// jobs needs chasing before someone with eight at 50 days. Within each engineer, oldest
// first, same as everywhere else.
//
// A single-engineer bucket gets no headings: when someone requests their own digest, or
// only one person has anything overdue, the names are noise.
function groupByEngineer(entries, nameOf) {
  const groups = new Map();
  for (const e of entries) {
    const who = nameOf(e.row.posted_by);
    if (!groups.has(who)) groups.set(who, []);
    groups.get(who).push(e);
  }
  const ordered = [...groups.entries()]
    .map(([who, list]) => ({ who, list, oldest: Math.max(...list.map((x) => x.age)) }))
    .sort((a, b) => b.oldest - a.oldest);
  return ordered;
}

// One bucket, grouped by engineer unless there is only one of them.
//
// Projects sit in a monospace block so the ages form a scannable column and the long
// slash-separated titles stop wrapping into each other. The engineer heading stays OUTSIDE
// the block — Slack ignores *bold* inside code fences.
function renderBucket(entries, nameOf) {
  const groups = groupByEngineer(entries, nameOf);
  if (groups.length <= 1) {
    return ['```', ...entries.map((o) => codeLine(o.row, o.age)), '```'];
  }
  const out = [];
  for (const g of groups) {
    out.push('');
    out.push('*' + g.who + '* (' + g.list.length + ')');
    out.push('```');
    for (const o of g.list) out.push(codeLine(o.row, o.age));
    out.push('```');
  }
  return out;
}

function buildDigest(input) {
  const { rows = [], asOf, mode = 'scheduled', nameOf = (u) => String(u || 'unassigned') } = input;

  // DELETED rows are excluded here as well as everywhere else — a deleted intake post
  // means the project is not being chased.
  const open = [];
  const untracked = [];
  for (const r of rows) {
    const status = String(r.status || '').trim();
    if (status === 'UNTRACKED') { untracked.push(r); continue; }
    if (status !== 'OPEN') continue;
    const age = ageDays(r.posted_date, asOf);
    if (age === null) continue;              // no usable date, cannot be aged or bucketed
    open.push({ row: r, age });
  }

  open.sort((a, b) => b.age - a.age);        // oldest first, §7 step 4

  // Age bands. Tara, 2026-09-03: 120 / 90 / 60 replaces the handoff's 90 / 45. Boundaries
  // are inclusive at the lower end, so a project at exactly 60 days lands in 60–89.
  // Anything under 60 is counted in the header but never listed (§7 step 3).
  const over120 = open.filter((o) => o.age >= 120);
  const band90 = open.filter((o) => o.age >= 90 && o.age < 120);
  const band60 = open.filter((o) => o.age >= 60 && o.age < 90);
  const band30 = open.filter((o) => o.age >= 30 && o.age < 60);
  const fresh = open.filter((o) => o.age < 30);

  const messages = [];
  const title = mode === 'manual'
    ? 'Posty — open projects as of ' + humanDate(asOf) + '  (requested)'
    : 'Posty — open projects as of ' + humanDate(asOf);

  let head = title;
  if (!over120.length && !band90.length && !band60.length && !band30.length) {
    head += '\n\nNothing over 30 days. ' + fresh.length + ' project' +
            (fresh.length === 1 ? '' : 's') + ' open and under 30 days.';
    messages.push(head);
  } else {
    messages.push(head);
    // Empty bands are skipped rather than printed as "(0)". With three of them, a run of
    // zero-count headers is noise that pushes the real work further down the DM.
    const bands = [['🔴 120+ days', over120], ['🟠 90–119 days', band90],
                   ['🟡 60–89 days', band60], ['🟢 30–59 days', band30]];
    for (const [label, bucket] of bands) {
      if (bucket.length) {
        messages.push(...chunk(label + ' (' + bucket.length + ')', renderBucket(bucket, nameOf)));
      }
    }
  }

  // Released this month — flat chronological log, matched on release_date's YYYY-MM.
  const month = String(asOf || '').slice(0, 7);
  const releasedThisMonth = rows.filter((r) =>
    String(r.status || '').trim() === 'RELEASED' &&
    String(r.release_date || '').startsWith(month));
  releasedThisMonth.sort((a, b) =>
    String(a.release_date).localeCompare(String(b.release_date)));
  if (releasedThisMonth.length) {
    const monthLabel = humanDate(month + '-01').replace(/^\d+ /, '');
    messages.push(...chunk('✅ Released in ' + monthLabel + ' (' + releasedThisMonth.length + ')',
      releasedThisMonth.map((r, i) => (i + 1) + '. ' + releasedLine(r))));
  }

  // §7 step 5. These carry no QU at all — not even a synthetic one — so no automation can
  // resolve them. Listed so they are visible, not so they can be actioned.
  //
  // The index deliberately keeps every unmatched message (§9 note 5 calls that acceptable
  // noise), which means UNTRACKED also collects plain channel chatter — "salamuch",
  // "Corgrats Eli!", a bare @mention. Those are noise in the index and merely untidy; in a
  // digest sent to two people they make the whole thing look unreliable.
  //
  // Every real project post in this channel uses " / " between fields. Requiring a slash
  // separates "QU-______ / SPOTIFY / Lea Lardizabal / H&M" — a real job awaiting a code —
  // from "this is DENTSU pala". The filter is presentation only: nothing is dropped from
  // the index, and the omitted count is printed so the filter can never hide a surprise.
  const realUntracked = untracked.filter((r) => String(r.source_text || '').includes('/'));
  const noise = untracked.length - realUntracked.length;

  if (realUntracked.length) {
    let header = 'Not tracked (' + realUntracked.length + ') — no QU code, needs manual check';
    if (noise) header += '\n(' + noise + ' non-project message' + (noise === 1 ? '' : 's') + ' omitted)';
    messages.push(...chunk(header,
      realUntracked.map((r) => escapeForSlack(r.source_text || '').replace(/\s*\n\s*/g, ' ').trim())));
  }

  // Row-count warning. The index grows ~500 released rows a year and full-sheet reads
  // slow past a few thousand. Warn well ahead — in the monthly digest Tara already reads —
  // so old released rows can be archived before it hurts. Tara, 2026-09-08.
  const SIZE_WARN = 4000;
  if (rows.length >= SIZE_WARN) {
    messages.push('🗄️ Heads up: the index is at ' + rows.length + ' rows. Past ~5,000, old '
      + 'released rows should be archived to keep Posty fast — worth planning, not urgent.');
  }

  return {
    messages,
    summary: {
      rows_total: rows.length,
      over120: over120.length,
      band90: band90.length,
      band60: band60.length,
      band30: band30.length,
      under30: fresh.length,
      untracked: realUntracked.length,
      untracked_noise: noise,
      total_open: open.length,
      released_this_month: releasedThisMonth.length,
    },
  };
}

const cfg = $('Normalize Request').first().json;
const rows = $input.all().map((i) => i.json);

const d = buildDigest({ rows, asOf: cfg.as_of, mode: cfg.mode, nameOf: engineerName });

// Fan out to one item per recipient per message. The Slack node runs once per item and
// preserves order, so each person receives the sections in sequence.
const out = [];
for (const user of cfg.recipients) {
  for (const text of d.messages) out.push({ json: { user, text, summary: d.summary } });
}
return out;

// Month-end nudge, one DM per post engineer who has open work.
//
// Separate from the digest: the digest tells Tara and regie about EVERYONE's open projects,
// this tells each engineer about their OWN. It is deliberately short — counts plus the
// oldest one — because the point is to prompt a look, not to be the list. Asking for the
// list is one reply away and that flow already exists.
//
// Anyone with nothing open gets no message. A monthly "you have 0 open projects" is the
// kind of notification people learn to ignore, which costs the ones that matter.
const POST_ENGINEERS = {
  'U025597KZ':   'regie',
  'U029T6N7U':   'philip',
  'U026N6E1R':   'tara',
  'U04DLRCAA':   'glenn',
  'U6UAKUP08':   'whannie',
  'U026LMLM4':   'rico',
  'U026N9FV9':   'vener',
  'U026N7KR7':   'topet',
  'U026MTBLM':   'richard',
  'U026R9SUQ':   'eddie boy',
  'U08V83R45QV': 'elijah',
  'U08V3CKDGJF': 'howard',
};

const cfg = $('Normalize Request').first().json;
const rows = $input.all().map((i) => i.json);

function ageDays(posted, today) {
  const a = Date.parse(String(posted) + 'T00:00:00Z');
  const b = Date.parse(String(today) + 'T00:00:00Z');
  return (Number.isFinite(a) && Number.isFinite(b)) ? Math.round((b - a) / 86400000) : null;
}
function escapeForSlack(t) {
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const byUser = new Map();
for (const r of rows) {
  if (String(r.status || '').trim() !== 'OPEN') continue;
  const who = String(r.posted_by || '').trim();
  if (!Object.prototype.hasOwnProperty.call(POST_ENGINEERS, who)) continue;  // unknown author
  const age = ageDays(r.posted_date, cfg.as_of);
  if (age === null) continue;
  if (!byUser.has(who)) byUser.set(who, []);
  byUser.get(who).push({ row: r, age });
}

const out = [];
for (const [user, list] of byUser) {
  list.sort((a, b) => b.age - a.age);   // oldest first
  const engName = POST_ENGINEERS[user] || 'there';
  // Intro, then one message per open project — the same line-by-line format as the
  // "remind" command, so each can be reacted to and updated on the spot. Tara 2026-09-08.
  out.push({ json: { user, qu_number: '', is_header: true,
    text: 'Month-end check \ud83d\udc4b Hi ' + engName + ', here are your ' + list.length
        + ' open project' + (list.length === 1 ? '' : 's') + '.\n\n'
        + 'For each one that is finished:\n'
        + '1. React with 🚀 or ✅ on it \u2014 I\'ll mark it released.\n'
        + '2. Reply to that same message with the release details.' } });
  for (const item of list) {
    out.push({ json: { user, qu_number: item.row.qu_number, is_header: false,
      text: escapeForSlack(String(item.row.source_text || '').replace(/\s*\n\s*/g, ' ').trim())
            + '  \u2014  ' + item.age + 'd' } });
  }
}
return out;

// Record each reminder message's ts as that project's notify_ts, so the engineer's
// reaction on it resolves back to the project. Pair responses to Build Reminders by order.
const inputs = $('Build Reminders').all().map((i) => i.json);
const resps = $input.all().map((i) => i.json);
function slackTs(r){ return String(r.message_timestamp || (r.message && r.message.ts) || '').trim(); }
const out = [];
for (let i = 0; i < resps.length; i++) {
  const src = inputs[i];
  if (!src || src.is_header || !src.qu_number) continue;
  const ts = slackTs(resps[i]); if (!ts) continue;
  out.push({ json: { qu_number: src.qu_number, notify_ts: ts, last_seen: new Date().toISOString() } });
}
return out;
